from pathlib import Path
import json,subprocess
root=Path('/home/ubuntu/spacepdhcg-joint-selection-v632');repo=root/'repo'
assert json.loads((root/'report.json').read_text())['success']
(repo/'build/performance/benchmark_joint_selection_v634.py').write_text('"""Matched full-download / device-winner timing on real archived itineraries.\n\nSearch surrogate only: changes to epochs are not newly certified trajectories.\n"""\nfrom pathlib import Path\nimport importlib.util,json,math,os,statistics,sys,time\nimport numpy as np\n\nsource=Path.cwd()\nspec=importlib.util.spec_from_file_location(\'joint_benchmark\',source/\'build/performance/joint-benchmark-v593/benchmark_joint.py\')\nb=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)\noutput=Path(sys.argv[1]);assert not output.exists()\nreport=dict(complete=False,scope=__doc__,core=b.file_record(os.environ[\'SPACEPDHCG_GTOC12_CUDA_LIBRARY\']),cases=[])\ncatalogue,bonus=b.load_catalogue(),b.load_bonus_table()\nos.environ[b.JOINT_FLAG]=\'1\'\narchive=source/\'results/lambda/2026-09-08/fleet-objective-v229/incumbent-sources\'\nwith b.using_lambert_backend(\'cuda\') as gpu:\n    for ship in (\'ship-01.json\',\'ship-02.json\'):\n        template,visits,arr,dep,fixture=b.prepare_fixture(archive/ship,catalogue,bonus,True)\n        arrivals,departures=b.matrices(visits,arr,dep,3.)\n        warm=b.warm_cache(gpu,template,visits,np.vstack((arr,arrivals)),np.vstack((dep,departures)))\n        for condition,cache in ((\'cold\',{}),(\'warm\',warm)):\n            expected=None\n            case=dict(ship=ship,visits=len(visits),candidates=len(arrivals),cache=condition,runs=[],fixture=fixture)\n            for block in range(6):\n                for mode in (0,1,1,0):\n                    os.environ[\'SPACEPDHCG_TEST_GTOC12_JOINT_DEVICE_SELECTION\']=str(mode)\n                    joint=b.clone(template,cache);before=b.counters(gpu)\n                    start=time.perf_counter_ns()\n                    result=b.evaluate_joint(joint,visits,arrivals,departures,minimum_objective=-math.inf)\n                    seconds=(time.perf_counter_ns()-start)*1e-9\n                    if expected is None:expected=result\n                    assert result[0]==expected[0]\n                    check=b.Checks(0.,0.);check.evaluation(result[1],expected[1],\'winner\')\n                    assert not check.errors,check.errors\n                    if block:\n                        case[\'runs\'].append(dict(mode=mode,seconds=seconds,winner=result[0],telemetry=b.counter_delta(before,gpu)))\n            medians={str(mode):statistics.median(r[\'seconds\'] for r in case[\'runs\'] if r[\'mode\']==mode) for mode in (0,1)}\n            case.update(median_seconds=medians,speedup=medians[\'0\']/medians[\'1\'],exact_winner_parity=True)\n            report[\'cases\'].append(case);output.write_text(json.dumps(b.plain(report),indent=2,allow_nan=False))\n            print(ship,condition,case[\'speedup\'],flush=True)\n    # This exercises actual successive search decisions with fresh geometry,\n    # beyond comparing a single fixed neighbourhood. It still is not SCvx.\n    report[\'controller\']=[]\n    for mode in (0,1):\n        os.environ[\'SPACEPDHCG_TEST_GTOC12_JOINT_DEVICE_SELECTION\']=str(mode)\n        joint=b.clone(template,{})\n        start=time.perf_counter()\n        result=joint.optimise_epochs(visits,arr,dep,mesh=(3.,1.),max_moves=3)\n        record=dict(mode=mode,seconds=time.perf_counter()-start,arrivals=result[0],departures=result[1],evaluation=result[2],accepted_moves=result[3],evaluations=joint.evaluations,lambert_requests=joint.lambert_evaluations)\n        if mode==0:reference=result\n        else:\n            np.testing.assert_array_equal(result[0],reference[0]);np.testing.assert_array_equal(result[1],reference[1]);assert result[3]==reference[3]\n            check=b.Checks(0.,0.);check.evaluation(result[2],reference[2],\'controller\');assert not check.errors,check.errors\n        report[\'controller\'].append(record)\nreport[\'complete\']=True\noutput.write_text(json.dumps(b.plain(report),indent=2,allow_nan=False))\n')
(root/'benchmark-runner.py').write_text('from pathlib import Path\nimport fcntl,hashlib,json,os,shutil,subprocess,time\nbuild=Path(\'/home/ubuntu/spacepdhcg-joint-selection-v632\');source=build/\'repo\'\nroot=build/\'benchmark-v634\';root.mkdir(exist_ok=False)\npython=\'/home/ubuntu/spacepdhcg/v1/.venv/bin/python\'\nlibrary=build/\'build/cuda/libspacepdhcg_cuda.so\'\nenv={k:v for k,v in os.environ.items() if not k.startswith(\'SPACEPDHCG_TEST_\')}\nenv.update(SPACEPDHCG_GTOC12_CUDA_LIBRARY=str(library),SPACEPDHCG_GTOC12_DATA=\'/home/ubuntu/spacepdhcg/gtoc12/benchmarks/gtoc12/data\',PYTHONPATH=str(source/\'src\'),OMP_NUM_THREADS=\'1\',OPENBLAS_NUM_THREADS=\'1\')\nscript=Path(\'build/performance/benchmark_joint_selection_v634.py\')\n\nreport=dict(complete=False,core_sha256=hashlib.sha256(library.read_bytes()).hexdigest(),checks=[])\ncommands=[(\'scalar-vs-batched\',str(source/\'build/performance/joint-benchmark-v593/benchmark_joint.py\'),[str(root/\'scalar-vs-batched.json\'),\'--source-root\',str(source),\'--archive-dir\',str(source/\'results/lambda/2026-09-08/fleet-objective-v229/incumbent-sources\'),\'--repeats\',\'3\']),(\'selection\',str(source/script),[str(root/\'selection.json\')])]\nwith open(\'/home/ubuntu/.spacepdhcg-gpu.lock\',\'a\') as lock:\n    fcntl.flock(lock,fcntl.LOCK_EX)\n    for name,path,args in commands:\n        boot="import sys,runpy;sys.meta_path=[f for f in sys.meta_path if f.__class__.__module__!=\'_editable_skbc_spacepdhcg\'];sys.argv="+repr([path,*args])+";runpy.run_path(sys.argv[0],run_name=\'__main__\')"\n        start=time.perf_counter()\n        with (root/(name+\'.log\')).open(\'x\') as log:result=subprocess.run([python,\'-c\',boot],cwd=source,env=env,stdout=log,stderr=subprocess.STDOUT)\n        report[\'checks\'].append(dict(name=name,returncode=result.returncode,seconds=time.perf_counter()-start));(root/\'report.json\').write_text(json.dumps(report,indent=2))\n        print(name,result.returncode,flush=True)\n        if result.returncode:print((root/(name+\'.log\')).read_text());raise SystemExit(result.returncode)\nreport[\'complete\']=True\n(root/\'report.json\').write_text(json.dumps(report,indent=2))\n')
with (root/'benchmark-runner.log').open('x') as log:child=subprocess.Popen(['/home/ubuntu/spacepdhcg/v1/.venv/bin/python',str(root/'benchmark-runner.py')],cwd=repo,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
print(json.dumps(dict(pid=child.pid)))
